Editor <- setRefClass("Editor",
  fields = list(content = "character", history = "list"),
  methods = list(
    initialize = function(...) {
      content <<- ""
      history <<- list()
      callSuper(...)
    },
    insert = function(text) {
      history[[length(history) + 1]] <<- content
      content <<- paste0(content, text)
    },
    delete = function(n) {
      history[[length(history) + 1]] <<- content
      content <<- substr(content, 1, max(0, nchar(content) - n))
    },
    undo = function() {
      if (length(history) > 0) {
        content <<- history[[length(history)]]
        history[[length(history)]] <<- NULL
      }
    },
    text = function() content
  )
)
